-- Batches
CREATE TABLE stock__lots (
    id INTEGER PRIMARY KEY,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    review_status TEXT NOT NULL DEFAULT 'confirmed',
    source TEXT NOT NULL DEFAULT 'person',
    batch_id INTEGER,
    edited_by_person INTEGER NOT NULL DEFAULT 0,
    deleted_at TEXT,
    item INTEGER REFERENCES stock__items(id) ON DELETE CASCADE,
    quantity REAL,
    expires TEXT,
    place INTEGER REFERENCES stock__places(id) ON DELETE RESTRICT,
    notes TEXT
);

CREATE INDEX stock__lots__item__idx ON stock__lots(item);

CREATE INDEX stock__lots__expires__idx ON stock__lots(expires);

CREATE INDEX stock__lots__place__idx ON stock__lots(place);

ALTER TABLE stock__movements ADD COLUMN lot INTEGER REFERENCES stock__lots(id) ON DELETE SET NULL;

ALTER TABLE stock__movements ADD COLUMN expires TEXT;

ALTER TABLE stock__movements ADD COLUMN place INTEGER REFERENCES stock__places(id) ON DELETE SET NULL;

CREATE INDEX stock__movements__lot__idx ON stock__movements(lot);

CREATE INDEX stock__movements__expires__idx ON stock__movements(expires);

CREATE INDEX stock__movements__place__idx ON stock__movements(place);

-- Each item recorded so far becomes one batch with its amount, use-by date and place, so nothing
-- is lost and the item's amount stays the same (decision 0053). Items with nothing on hand, no
-- date and no stock in or out need no batch. A deleted item's batch is deleted with it.
INSERT INTO stock__lots (created_at, updated_at, source, deleted_at, item, quantity, expires, place)
SELECT created_at, updated_at, 'module:stock', deleted_at, id, COALESCE(quantity, 0), expires, place
FROM stock__items
WHERE COALESCE(quantity, 0) > 0 OR expires IS NOT NULL
   OR id IN (SELECT item FROM stock__movements);

-- Stock in and out recorded so far belongs to that batch, so editing or deleting it later
-- changes the right count. Nothing is replayed: the batch already holds today's amount.
UPDATE stock__movements
SET lot = (SELECT l.id FROM stock__lots l WHERE l.item = stock__movements.item)
WHERE lot IS NULL;

-- A batch made for an item that was already deleted is recorded as deleted along with that item,
-- so restoring the item brings its stock back with it (decision 0050).
INSERT INTO core__audit (at, actor, action, table_name, record_id, before, after)
SELECT deleted_at, 'module:stock', 'delete', 'stock__lots', id, NULL,
       json_object('with', 'stock__items:' || item, 'kept_effect', json('false'))
FROM stock__lots WHERE deleted_at IS NOT NULL;

-- An item with nothing left has no use-by date to warn about.
UPDATE stock__items SET expires = NULL WHERE COALESCE(quantity, 0) <= 0;

-- Where things are is now kept on each batch. The item's old place is cleared so it cannot
-- quietly stop that place from being deleted later.
UPDATE stock__items SET place = NULL;
